@JsonInclude(JsonInclude.Include.NON_NULL)
@JsonIgnoreProperties(ignoreUnknown = true)
@JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
@Schema(description = "Contains information about a user's agreement for recurring payments. " +
        "An agreement represents an understanding between you and your paying user that you'll use their card to make ongoing payments for a service.")
public class Agreement {
    private String externalId;
    private String reference;
    private String description;
    private String status;
    private String createdDate;
    private PaymentInstrument paymentInstrument;
    private String userIdentifier;
    private String cancelledDate;

    @JsonProperty("agreement_id")
    @Schema(description = "The unique ID GOV.UK Pay automatically associated with this agreement when you created it.", 
            example = "cgc1ocvh0pt9fqs0ma67r42l58")
    public String getExternalId() {
        return externalId;
    }

    @Schema(description = "The reference you sent when creating this agreement.",
            example = "CT-22-23-0001")
    public String getReference() {
        return reference;
    }

    @Schema(description = "The description you sent when creating this agreement.",
            example = "Dorset Council 2022/23 council tax subscription.")
    public String getDescription() {
        return description;
    }

    @Schema(description = "The status of this agreement. " +
            "You can [read more about the meanings of each agreement status.](https://docs.payments.service.gov.uk/recurring_payments/#understanding-agreement-status)",
            allowableValues = {"created", "active", "cancelled", "inactive"})
    public String getStatus() {
        return Optional.ofNullable(status).map(String::toLowerCase).orElse(null);
    }

    @Schema(description = "The date and time you created this agreement. " +
            "This value uses Coordinated Universal Time (UTC) and ISO 8601 format – `YYYY-MM-DDThh:mm:ss.sssZ`.",
            example = "2022-07-08T14:33:00.000Z")
    public String getCreatedDate() {
        return createdDate;
    }

    @Schema(description = "The identifier you sent when creating this agreement. " +
            "`user_identifier` helps you identify users in your records.",
            example = "user-3fb81107-76b7-4910")
    public String getUserIdentifier() {
        return userIdentifier;
    }

    @Schema(description = "The date and time this agreement was cancelled. " +
            "This value uses Coordinated Universal Time (UTC) and ISO 8601 format – `YYYY-MM-DDThh:mm:ss.sssZ`.",
            example = "2022-07-08T14:33:00.000Z")
    public String getCancelledDate() {
        return cancelledDate;
    }

    public PaymentInstrument getPaymentInstrument() {
        return paymentInstrument;
    }

    public Agreement(String externalId, String reference, String description, String status, String createdDate,
                     PaymentInstrument paymentInstrument, String userIdentifier, String cancelledDate) {
        this.externalId = externalId;
        this.reference = reference;
        this.description = description;
        this.status = status;
        this.createdDate = createdDate;
        this.paymentInstrument = paymentInstrument;
        this.userIdentifier = userIdentifier;
        this.cancelledDate = cancelledDate;
    }

    public static Agreement from(AgreementLedgerResponse agreementLedgerResponse) {
        return new Agreement(
                agreementLedgerResponse.getExternalId(),
                agreementLedgerResponse.getReference(),
                agreementLedgerResponse.getDescription(),
                agreementLedgerResponse.getStatus(),
                agreementLedgerResponse.getCreatedDate(),
                Optional.ofNullable(agreementLedgerResponse.getPaymentInstrument()).map(PaymentInstrument::from).orElse(null),
                agreementLedgerResponse.getUserIdentifier(),
                agreementLedgerResponse.getCancelledDate());
    }

    @JsonInclude(JsonInclude.Include.NON_NULL)
    @JsonIgnoreProperties(ignoreUnknown = true)
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class PaymentInstrument {
        private final CardDetailsFromResponse cardDetails;
        private final String createdDate;
        private final String type;

        public PaymentInstrument(CardDetailsFromResponse cardDetails, String createdDate, String type) {
            this.cardDetails = cardDetails;
            this.createdDate = createdDate;
            this.type = type;
        }

        public static PaymentInstrument from(AgreementLedgerResponse.PaymentInstrumentLedgerResponse paymentInstrumentLedgerResponse) {
            return new PaymentInstrument(paymentInstrumentLedgerResponse.getCardDetails(), paymentInstrumentLedgerResponse.getCreatedDate(), paymentInstrumentLedgerResponse.getType());
        }


        @Schema(name = "CardDetails")
        public CardDetailsFromResponse getCardDetails() {
            return cardDetails;
        }

        @Schema(description = "The date and time you created this payment instrument. " +
                "This value uses Coordinated Universal Time (UTC) and ISO 8601 format – `YYYY-MM-DDThh:mm:ss.sssZ`.",
                example = "2022-07-08T14:33:00.000Z")
        public String getCreatedDate() {
            return createdDate;
        }

        @Schema(description = "The type of payment instrument.",
                allowableValues = {"card"})
        public String getType() {
            return Optional.ofNullable(type).map(String::toLowerCase).orElse(null);
        }
    }
}

@JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
public class AgreementSearchResults implements SearchPagination {

    @Schema(name = "total", example = "100", description = "Total number of agreements matching your search criteria.")
    private int total;
    @Schema(name = "count", example = "20", description = "Number of agreements on the current page of search results.")
    private int count;
    @Schema(name = "page", example = "1",
            description = "The [page of agreements you’re viewing]" +
                    "(https://docs.payments.service.gov.uk/api_reference/#pagination). " +
                    "To view other pages, make this request again using the `page` parameter.")
    private int page;
    private List<Agreement> results;
    @JsonProperty("_links")
    @Schema(name = "_links")
    SearchNavigationLinks links;

    public AgreementSearchResults(int total, int count, int page, List<Agreement> results, SearchNavigationLinks links) {
        this.total = total;
        this.count = count;
        this.page = page;
        this.results = results;
        this.links = links;
    }

    @Override
    public int getTotal() {
        return total;
    }

    @Override
    public int getCount() {
        return count;
    }

    @Override
    public int getPage() {
        return page;
    }

    @Schema(name = "results", description = "Contains agreements matching your search criteria.")
    public List<Agreement> getResults() {
        return results;
    }

    @Override
    public SearchNavigationLinks getLinks() {
        return links;
    }
}

@Schema(description = "The Agreement Request Payload")
@JsonIgnoreProperties(ignoreUnknown = true)
public class CreateAgreementRequest {

    public static final String USER_IDENTIFIER_FIELD = "user_identifier";

    public static final int MIN_LENGTH = 1;
    public static final int MAX_LENGTH = 255;

    @JsonProperty("reference")
    @Size(min= MIN_LENGTH, max = MAX_LENGTH, message = "Must be less than or equal to {max} characters length")
    private String reference;

    @JsonProperty("description")
    @Size(min= MIN_LENGTH, max = MAX_LENGTH, message = "Must be less than or equal to {max} characters length")
    private String description;

    @JsonProperty(USER_IDENTIFIER_FIELD)
    @Size(min= MIN_LENGTH, max = MAX_LENGTH, message = "Must be less than or equal to {max} characters length")
    private String userIdentifier;

    public CreateAgreementRequest() {
        // for Jackson
    }

    public CreateAgreementRequest(CreateAgreementRequestBuilder builder) {
        this.reference = builder.getReference();
        this.description = builder.getDescription();
        this.userIdentifier = builder.getUserIdentifier();
    }

    @Schema(description = "Associate a reference with this agreement to help you identify it. Limited to 255 characters.",
    example = "CT-22-23-0001")
    public String getReference() {
        return reference;
    }

    @Schema(description = "A human-readable description of the purpose of the agreement for recurring payments. " +
            "We’ll show the description to your user when they make their first payment to activate this agreement. " +
            "Limited to 255 characters.",
            example = "Dorset Council 2022/23 council tax subscription.")
    public String getDescription() {
        return description;
    }

   @Schema(description = "Associate an identifier with the user who will enter into this agreement with your service." +
           "user_identifier is not unique – multiple agreements can have identical user_identifier values." +
           "You should not include personal data in user_identifier.",
            example = "user-3fb81107-76b7-4910")
    public String getUserIdentifier() {
        return userIdentifier;
    }

    public String toConnectorPayload() {
        var stringBuilder = new JsonStringBuilder()
                .add("reference", this.getReference())
                .add("description", this.getDescription());

        if (this.getUserIdentifier() != null) {
            stringBuilder.add("user_identifier", this.getUserIdentifier());
        }
        return stringBuilder.build();
    }

    @Override
    public boolean equals(Object o) {   
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        CreateAgreementRequest that = (CreateAgreementRequest) o;
        return Objects.equals(reference, that.reference) && Objects.equals(description, that.description) && Objects.equals(userIdentifier, that.userIdentifier);
    }

    @Override
    public int hashCode() {
        return Objects.hash(reference, description, userIdentifier);
    }
}

public class AgreementsService {
    private static final String AGREEMENTS_PATH = "/v1/agreements";
    private final ConnectorService connectorService;
    private final LedgerService ledgerService;
    private final PaginationDecorator paginationDecorator;

    @Inject
    public AgreementsService(ConnectorService connectorService, LedgerService ledgerService, PaginationDecorator paginationDecorator) {
        this.connectorService = connectorService;
        this.ledgerService = ledgerService;
        this.paginationDecorator = paginationDecorator;
    }

    public AgreementCreatedResponse createAgreement(Account account, CreateAgreementRequest createAgreementRequest) {
        return connectorService.createAgreement(account, createAgreementRequest);
    }

    public Response cancelAgreement(Account account, String agreementId) {
        connectorService.cancelAgreement(account, agreementId);

        return Response.noContent().build();
    }

    public AgreementLedgerResponse getAgreement(Account account, String agreementId) {
        return ledgerService.getAgreement(account, agreementId);
    }

    public AgreementSearchResults searchAgreements(Account account, AgreementSearchParams params) {
        SearchResults<AgreementLedgerResponse> ledgerResponse = ledgerService.searchAgreements(account, params);
        return processLedgerResponse(ledgerResponse);
    }

    private AgreementSearchResults processLedgerResponse(SearchResults<AgreementLedgerResponse> searchResults) {
        return new AgreementSearchResults(searchResults.getTotal(),
                searchResults.getCount(),
                searchResults.getPage(),
                searchResults.getResults().stream().map(Agreement::from).collect(Collectors.toUnmodifiableList()),
                paginationDecorator.transformLinksToPublicApiUri(searchResults.getLinks(), AGREEMENTS_PATH));
    }
}

