                .path("/v1/payments/{paymentId}/refunds/{refundId}")
                .build(paymentId, refundEntity.getRefundId());

        URI paymentLink = UriBuilder.fromUri(baseUrl)
                .path("/v1/payments/{paymentId}")
                .build(paymentId);

