public class JsonStringBuilder {
    private static final ObjectWriter WRITER = new ObjectMapper()
            .writer();

    private String root;
    private Map<String, Object> map;

    private boolean prettyPrint;

    public JsonStringBuilder() {
        map = new LinkedHashMap<>();
        prettyPrint = true;
    }

    public JsonStringBuilder noPrettyPrint() {
        prettyPrint = false;
        return this;
    }

    public JsonStringBuilder addRoot(String root) {
        this.root = root;
        return this;
    }

    public JsonStringBuilder add(String key, Object value) {
        if (value != null) {
            map.put(key, value);
        }
        return this;
    }

    public JsonStringBuilder addToMap(String mapKey, String key, Object value) {
        Map<String, Object> nestedMap = ensureNestedMap(mapKey);
        nestedMap.put(key, value);
        return this;
    }

    public JsonStringBuilder addToMap(String mapKey) {
        ensureNestedMap(mapKey);
        return this;
    }

    public JsonStringBuilder addToNestedMap(String key, Object value, String... mapKeys) {
        Map<String, Object> localMap = map;
        for (String mapKey : mapKeys) {
            localMap = ensureNestedMap(localMap, mapKey);
        }
        localMap.put(key, value);
        return this;
    }

    public String build() {
        ObjectWriter writer = WRITER;
        if (prettyPrint) {
            writer = writer.withDefaultPrettyPrinter();
        }

        if (root != null) {
            writer = writer
                    .with(SerializationFeature.WRAP_ROOT_VALUE)
                    .withRootName(root);
        }

        return asJsonString(writer, map);
    }

    private String asJsonString(ObjectWriter writer, Object object) {
        try {
            return writer.writeValueAsString(object);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("Error processing json object to string", e);
        }
    }

    @SuppressWarnings("unchecked")
    private Map<String, Object> ensureNestedMap(String mapKey) {
        Map<String, Object> nestedMap = (Map<String, Object>) map.get(mapKey);
        if (nestedMap == null) {
            nestedMap = new LinkedHashMap<>();
            map.put(mapKey, nestedMap);
        }
        return nestedMap;
    }

    @SuppressWarnings("unchecked")
    private Map<String, Object> ensureNestedMap(Map<String, Object> localMap, String mapKey) {
        Map<String, Object> nestedMap = (Map<String, Object>) localMap.get(mapKey);
        if (nestedMap == null) {
            nestedMap = new LinkedHashMap<>();
            localMap.put(mapKey, nestedMap);
        }
        return nestedMap;
    }
}

public class ConnectorResponseErrorException extends RuntimeException {

    private static final Logger LOGGER = LoggerFactory.getLogger(ConnectorResponseErrorException.class);

    private ConnectorErrorResponse error;
    private int status;

    public ConnectorResponseErrorException(Response response) {
        super(response.toString());
        this.status = response.getStatus();
        this.error = readError(response);
        response.close();
    }

    ConnectorResponseErrorException(ConnectorResponseErrorException exception) {
        super(exception);
        this.status = exception.status;
        this.error = exception.error;
    }

    ConnectorResponseErrorException(Throwable cause) {
        super(cause);
    }

    public int getErrorStatus() {
        return status;
    }

    public ErrorIdentifier getErrorIdentifier() {
        return error == null ? ErrorIdentifier.GENERIC : error.errorIdentifier;
    }

    public String getReason() {
        if (error != null) {
            return error.getReason();
        }
        return null;
    }

    public boolean hasReason() {
        return this.error != null && this.error.getReason() != null;
    }

    private ConnectorErrorResponse readError(Response response) {
        ConnectorErrorResponse connectorError = null;
        try {
            connectorError = response.readEntity(ConnectorErrorResponse.class);
        } catch (Exception exception) {
            LOGGER.debug("Could not read error response from connector", exception);
        }
        return connectorError;
    }

    private String getResponseBody() {
        if (error != null) {
            return error.toString();
        }
        return null;
    }

    @Override
    public String getMessage() {
        String body = getResponseBody();
        if (body != null) {
            return super.getMessage() + " and body " + body;
        }
        return super.getMessage();
    }

    public String getConnectorErrorMessage() {
        return error.message.stream().findFirst()
                .orElseThrow(() -> new InternalServerException("Error deserializing connector error message"));
    }

    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class ConnectorErrorResponse {

        @JsonProperty("error_identifier")
        private ErrorIdentifier errorIdentifier;

        private String reason;

        private List<String> message;

        // Needed for Jackson deserialization from Responses
        public ConnectorErrorResponse() {

        }

        public ConnectorErrorResponse(ErrorIdentifier errorIdentifier, List<String> message) {
            this(errorIdentifier, null, message);
        }

        public ConnectorErrorResponse(ErrorIdentifier errorIdentifier, String reason, List<String> message) {
            this.errorIdentifier = errorIdentifier;
            this.reason = reason;
            this.message = message;
        }

        public ErrorIdentifier getErrorIdentifier() {
