public class CustomSupportedLanguageDeserializer extends StdDeserializer<SupportedLanguage> {

    public CustomSupportedLanguageDeserializer() {
        this(null);
    }

    public CustomSupportedLanguageDeserializer(Class<?> vc) {
        super(vc);
    }

    @Override
    public SupportedLanguage deserialize(JsonParser jsonparser, DeserializationContext context) throws IOException {
        return SupportedLanguage.fromIso639AlphaTwoCode(jsonparser.getText());
    }
}

public class WalletDeserializer extends JsonDeserializer<Wallet> {

    private static final Logger logger = LoggerFactory.getLogger(WalletDeserializer.class);

    @Override
    public Wallet deserialize(JsonParser jsonParser, DeserializationContext deserializationContext)
            throws IOException {
        String value = jsonParser.getText().toUpperCase();
        try {
            return Wallet.valueOf(value);
        } catch (IllegalArgumentException e) {
            logger.error(format("Value [%s] matches no known wallet types", value));
            return null;
        }
    }
}

