public class CardExpiryValidator implements ConstraintValidator<ValidCardExpiryDate, String> {

    @Override
    public boolean isValid(String value, ConstraintValidatorContext context) {
        return value == null || CardExpiryDate.CARD_EXPIRY_DATE_PATTERN.matcher(value).matches();
    }

}

public class CardFirstSixDigitsValidator implements ConstraintValidator<ValidCardFirstSixDigits, String> {

    private Pattern pattern = Pattern.compile("\\d{6}");

    @Override
    public boolean isValid(String value, ConstraintValidatorContext context) {

        if (value == null) {
            return true;
        }

        return pattern.matcher(value).matches();

    }

}

public class CardLastFourDigitsValidator implements ConstraintValidator<ValidCardLastFourDigits, String> {

    private Pattern pattern = Pattern.compile("\\d{4}");

    @Override
    public boolean isValid(String value, ConstraintValidatorContext context) {

        if (value == null) {
            return true;
        }

        return pattern.matcher(value).matches();

    }
}

public class CardTypeValidator implements ConstraintValidator<ValidCardType, String> {

    private static final HashSet<String> CARD_TYPES = new HashSet<>();

    static {
        CARD_TYPES.add("master-card");
        CARD_TYPES.add("visa");
        CARD_TYPES.add("maestro");
        CARD_TYPES.add("diners-club");
        CARD_TYPES.add("american-express");
        CARD_TYPES.add("jcb");
    }

    @Override
    public boolean isValid(String value, ConstraintValidatorContext context) {

        if (value == null) {
            return true;
        }

        return CARD_TYPES.contains(value);

    }
}

public class ZoneDateTimeValidator implements ConstraintValidator<ValidZonedDateTime, String> {

    @Override
    public boolean isValid(String date, ConstraintValidatorContext context) {

        if (date == null) {
            return true;
        }

        try {
            ZonedDateTime.parse(date);
            return true;
        } catch (DateTimeParseException e) {
            return false;
        }
    }
}

